import nki
import nki.isa as nisa
import nki.language as nl

@nki.jit
def nki_matmul_basic_(lhsT, rhs):
    M = lhsT.shape[1]
    N = rhs.shape[1]
    K = lhsT.shape[0]
    tile = nl.ndarray((M, N), dtype=lhsT.dtype, buffer=nl.sbuf)
    out = nl.ndarray((M, N), dtype=lhsT.dtype, buffer=nl.shared_hbm)
    for m in nl.affine_range(M):
        for n in nl.affine_range(N):
            for k in nl.affine_range(K):
                tile[m, n] += lhsT[k, m] * rhs[k, n]
    nisa.tensor_copy(dst=out, src=tile)
    return out
